def revise(materials, rows):
    general = '24 Punkte, bestanden ab 15. Beide eigenständigen Fälle bearbeiten. Alle Profile, Betriebe und Institutionen sind eigene fiktive Unterrichtsmodelle; nur verlinkte BAuA-Berichte sind empirische Quellen. Reflexion darf ein ausdrücklich simuliertes Profil oder freiwillig ausgewählte eigene Bezugspunkte nutzen. Private Angaben bleiben lokal; Bewerbungen oder echte Kontakte sind nicht erforderlich.'
    fair = 'Bewertung der ganzen Arbeit: Nachvollziehbare unvollständige Leistungen und begründete alternative Urteile zählen. Eine Leistung kann an anderer Stelle derselben Arbeit gezeigt sein; Aufgabenüberschriften sind keine Pflicht. Einzelne Rechen-, Rundungs- oder Detailfehler, Unsicherheit oder unvollständige Begründungen lösen keine Gesamtbegrenzung aus. '
    explicit_en = {'Drequires':'D requires','Crequires':'C requires','Coffers':'C offers','The12-month':'The 12-month','F’s2023':'F’s 2023','Istates':'I states','F’s2023anecdote':'F’s 2023 anecdote','Ggives':'G gives','Gvaries':'G varies','Fprovides':'F provides','Fis fixed':'F is fixed','Gmay':'G may','D’s weekly':'D’s weekly','D’s2023':'D’s 2023','Gis':'G is','Kshares':'K shares','Ssubject':'S subject','Bwith':'B with','Dcan':'D can','Csocial':'C social','Dbecomes':'D becomes','Xfirst':'X first','D’sweekly':'D’s weekly','Swhile':'S while','Son-call':'S on-call','Dand':'D and','D’s':'D’s','Drequires':'D requires','DorCopen':'D or C open','M/date/question':'M/date/question','Aoptions':'A options','F/Hconflict':'F/H conflict','Nfor':'N for','Xupdate':'X update','Dapplications':'D applications','C/Tätigkeit':'C/Tätigkeit','Bcommunication':'B communication','D/C':'D/C','G’s':'G’s','Dand C':'D and C','Dfirst':'D first','A’s':'A’s','F is fixed1000':'F is fixed 1000','A’s actual':'A’s actual'}
    for k,m in enumerate(materials):
        es=m['examData'];ts=rows[k]['wholeTaskSolutionFourMarkCriteria'];assert len(ts)==len(TEXT[k])==6
        for j,(task,solution,marks) in enumerate(TEXT[k]):
            ts[j]['taskDe']=task;ts[j]['solutionDe']=solution;ts[j]['fourMarksDe']=marks
            es['scoring']['steps'][j]['description']='Je 1 Punkt: '+'; '.join(marks)+'.'
        rows[k]['necessaryCoreBoundaryDe']=CORE[k]
        es['taskContent']=f'**{m["title"]} — {general}**\n\n'+DATA[k]+'\n\n**Aufgaben, jeweils 4 Punkte.**\n'+'\n'.join(f'{j+1}. {t["taskDe"]}' for j,t in enumerate(ts))+'\n\n'+fair+CORE[k]
        es['solutionContent']='\n\n'.join(f'{j+1}. {t["solutionDe"]}\nBewertung, je 1 Punkt: '+'; '.join(t['fourMarksDe'])+'.' for j,t in enumerate(ts))+'\n\n'+fair+CORE[k]
        for key in ['taskContentEn','solutionContentEn']:
            for before,after in explicit_en.items():es[key]=es[key].replace(before,after)
